const rawInput = $input.first()?.json || {};
let rawAgent3Json = rawInput.agent3_json ?? rawInput['Agent 3 JSON 结果'] ?? rawInput.data ?? '';

// 去掉用户从 Markdown 里复制时可能带上的 ```json 代码块外壳。
function stripMarkdownFence(value) {
  const text = typeof value === 'string' ? value.trim() : value;
  if (typeof text !== 'string') return text;
  return text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
}

// 自动寻找 Agent 3 可能输出脚本数组的位置。
function findScripts(value) {
  if (Array.isArray(value)) return value;
  if (!value || typeof value !== 'object') return [];
  const possibleKeys = ['scripts', 'script_results', 'approved_scripts', 'results', 'records'];
  for (const key of possibleKeys) {
    if (Array.isArray(value[key])) return value[key];
  }
  for (const key of Object.keys(value)) {
    if (Array.isArray(value[key])) return value[key];
  }
  return [value];
}

function text(value) {
  return String(value ?? '').trim();
}

// 把不同来源的字段统一成 Agent 4 能理解的脚本结构。
function normalizeScript(script, index) {
  return {
    ...script,
    script_id: text(script.script_id || script.id || `agent3_script_${index + 1}`),
    video_title: text(script.video_title || script.title || script.topic || `Untitled Script ${index + 1}`),
    hook: text(script.hook || script.Hook || script.video_hook),
    body: text(script.body || script.Body || script.main_content || script.script_body),
    cta: text(script.cta || script.CTA || script.call_to_action),
    hashtags: Array.isArray(script.hashtags) ? script.hashtags : [],
    source_index: index + 1,
  };
}

try {
  let parsed = rawAgent3Json;
  if (typeof parsed === 'string') parsed = JSON.parse(stripMarkdownFence(parsed));
  const scripts = findScripts(parsed).map(normalizeScript).filter((script) => script.video_title);
  return [{ json: { status: 'parsed', parse_error: '', source_agent: parsed?.agent || 'agent_3', scripts, total_scripts: scripts.length } }];
} catch (error) {
  return [{ json: { status: 'error', parse_error: `Agent 3 JSON 解析失败：${error.message}`, scripts: [], total_scripts: 0 } }];
}

const data = $input.first()?.json || {};

if (data.status === 'error') {
  return [{ json: { ...data, visual_input_scripts: [], selected_count: 0 } }];
}

function truthy(value) {
  return value === true || value === 'true' || value === 'Yes' || value === 'yes' || value === 'approved';
}

function isReadyForAgent4(script) {
  return truthy(script.ready_for_agent4)
    || truthy(script.qa_passed)
    || String(script.status || '').toLowerCase() === 'approved'
    || truthy(script.ready_for_next_agent)
    || truthy(script.qa?.passed);
}

const visualInputScripts = (Array.isArray(data.scripts) ? data.scripts : []).filter(isReadyForAgent4).slice(0, 5);

return [{ json: { ...data, status: visualInputScripts.length > 0 ? 'ready_for_visual' : 'insufficient_data', visual_input_scripts: visualInputScripts, selected_count: visualInputScripts.length, selection_note: visualInputScripts.length > 0 ? '已选择可进入 Agent 4 的脚本，最多处理前 5 条。' : '没有 ready_for_agent4、qa_passed、approved 或 ready_for_next_agent 的脚本，Agent 4 不会编造视觉方案。' } }];

const data = $input.first()?.json || {};

if (data.status === 'error' || data.status === 'insufficient_data') {
  return [{ json: { ...data, draft_visual_plans: [] } }];
}

function text(value) { return String(value ?? '').trim(); }
function shortText(value, max = 38) {
  const clean = text(value).replace(/\s+/g, ' ');
  return clean.length > max ? `${clean.slice(0, max - 1)}…` : clean;
}
function splitSentences(value) {
  const parts = text(value).split(/(?<=[.!?])\s+/).map((part) => part.trim()).filter(Boolean);
  return parts.length ? parts : [text(value) || 'Show the wellness idea in a calm, educational way.'];
}
function chooseStyle(script) {
  const combined = `${script.video_title} ${script.hook} ${script.body}`.toLowerCase();
  if (combined.includes('evening') || combined.includes('night')) return 'Cozy Evening Ritual';
  if (combined.includes('rooibos') || combined.includes('tea') || combined.includes('botanical')) return 'Botanical Museum';
  if (combined.includes('product') || combined.includes('close')) return 'Educational Product Close-up';
  if (combined.includes('routine') || combined.includes('lifestyle')) return 'Documentary Lifestyle';
  return 'Natural Wellness';
}
function promptFor(scene, style) {
  return `Vertical 9:16 composition, ${scene.subject} in ${scene.setting}, ${scene.visual_description}, ${scene.shot_type}, ${scene.camera_movement}, ${style} visual style, soft natural lighting, realistic details, calm wellness mood, no text unless specified, no medical claims, no logos, no watermark.`;
}
function videoPromptFor(scene, style) {
  return `Vertical 9:16 short-form video shot, ${scene.duration_seconds} seconds, ${scene.subject} in ${scene.setting}, ${scene.camera_movement}, ${scene.visual_description}, ${style} style, smooth pacing, realistic lifestyle footage, no medical claims, no logos, no watermark.`;
}
function makeScene(number, start, duration, section, narration, script, style) {
  const end = start + duration;
  const isHook = section === 'Hook';
  const isCta = section === 'CTA';
  const subject = isHook ? 'a warm herbal tea cup and botanical ingredients' : (isCta ? 'a creator holding a notebook beside herbal tea' : 'hands preparing herbal tea with botanical details');
  const setting = style === 'Cozy Evening Ritual' ? 'a cozy evening kitchen with warm lamps' : 'a clean vertical wellness studio with botanical props';
  const visualDescription = isHook
    ? `Create an immediate first-3-second visual hook for ${script.video_title}: steam, close-up texture, and a quick reveal.`
    : (isCta ? 'End with a calm save-and-follow visual, notebook checklist, and gentle product-free lifestyle framing.' : `Show the idea visually while avoiding medical promises: ${shortText(narration, 90)}`);
  const base = {
    scene_number: number,
    start_time: `${start}s`,
    end_time: `${end}s`,
    duration_seconds: duration,
    script_section: section,
    narration_text: narration,
    visual_description: visualDescription,
    shot_type: isHook ? 'macro close-up' : (isCta ? 'medium lifestyle shot' : 'close-up with cutaway'),
    camera_movement: isHook ? 'slow push-in' : (isCta ? 'gentle handheld hold' : 'slow tilt and detail cut'),
    subject,
    setting,
    props: ['herbal tea cup', 'botanical ingredient', 'neutral ceramic cup', 'wooden table'],
    on_screen_text: shortText(isHook ? script.video_title : narration, 34),
    b_roll_suggestion: isHook ? 'steam rising from tea, ingredient pour, quick product-free reveal' : 'tea preparation, ingredient texture, lifestyle routine details',
    transition: number === 1 ? 'quick warm cut' : 'soft match cut',
    continuity_notes: `Keep the same ${style} palette, same cup, same botanical props, and consistent warm neutral lighting.`,
    safety_notes: 'Keep visuals educational and non-clinical; avoid doctor endorsement, FDA badges, clinical certification, medication scenes, or before-and-after health transformations.',
  };
  return { ...base, image_prompt: promptFor(base, style), video_prompt: videoPromptFor(base, style) };
}
function buildScenes(script, style) {
  const hook = text(script.hook) || `A simple visual way to understand ${script.video_title}.`;
  const bodyParts = splitSentences(script.body).slice(0, 5);
  const cta = text(script.cta) || 'Save this for general wellness education and review before publishing.';
  const durations = [3, ...bodyParts.map(() => 5), 4];
  const sections = ['Hook', ...bodyParts.map(() => 'Body'), 'CTA'];
  const narrations = [hook, ...bodyParts, cta];
  let start = 0;
  return narrations.map((narration, index) => {
    const scene = makeScene(index + 1, start, durations[index], sections[index], narration, script, style);
    start += durations[index];
    return scene;
  });
}

const draftVisualPlans = (data.visual_input_scripts || []).map((script, index) => {
  const visualStyle = chooseStyle(script);
  const scenes = buildScenes(script, visualStyle);
  const duration = scenes.reduce((sum, scene) => sum + Number(scene.duration_seconds || 0), 0);
  return { script_id: script.script_id || `agent3_script_${index + 1}`, video_title: script.video_title, visual_style: visualStyle, aspect_ratio: '9:16', estimated_duration_seconds: duration, scene_count: scenes.length, scenes, source_script: { hook: script.hook, body: script.body, cta: script.cta } };
});

return [{ json: { ...data, status: 'visual_planned', draft_visual_plans: draftVisualPlans } }];

const data = $input.first()?.json || {};

if (data.status === 'error' || data.status === 'insufficient_data') {
  return [{ json: { ...data, qa_visual_plans: [] } }];
}

const riskyPhrases = ['cure', 'treat', 'prevent disease', 'reverse disease', 'replace medication', 'stop medication', 'guaranteed result', 'fda approved', 'clinically proven', 'doctor recommended', 'before and after cure', 'diabetes cured', '治愈', '治疗', '替代药物', '停止服药', '保证有效'];
const requiredSceneFields = ['scene_number', 'start_time', 'end_time', 'duration_seconds', 'script_section', 'narration_text', 'visual_description', 'shot_type', 'camera_movement', 'subject', 'setting', 'props', 'on_screen_text', 'b_roll_suggestion', 'image_prompt', 'video_prompt', 'transition', 'continuity_notes', 'safety_notes'];

function text(value) { return String(value ?? '').trim(); }
function hasRisk(value) {
  const lower = text(value).toLowerCase();
  return riskyPhrases.filter((phrase) => lower.includes(phrase.toLowerCase()));
}
function parseSeconds(value) {
  const match = text(value).match(/\d+(?:\.\d+)?/);
  return match ? Number(match[0]) : 0;
}
function safePrompt(scene) {
  return `Vertical 9:16 composition, ${text(scene.subject) || 'wellness lifestyle subject'}, ${text(scene.setting) || 'clean natural wellness setting'}, realistic details, soft natural lighting, no text unless specified, no medical claims, no logos, no watermark.`;
}
function repairScene(scene, index, corrections) {
  const repaired = { ...scene };
  if (!repaired.scene_number || repaired.scene_number !== index + 1) {
    repaired.scene_number = index + 1;
    corrections.push(`修复镜头编号为 ${index + 1}。`);
  }
  if (!text(repaired.script_section)) { repaired.script_section = index === 0 ? 'Hook' : 'Body'; corrections.push(`补充第 ${index + 1} 个镜头的脚本段落。`); }
  if (!text(repaired.duration_seconds) || Number(repaired.duration_seconds) <= 0) { repaired.duration_seconds = index === 0 ? 3 : 5; corrections.push(`补充第 ${index + 1} 个镜头时长。`); }
  if (!text(repaired.start_time)) repaired.start_time = `${index * 5}s`;
  if (!text(repaired.end_time)) repaired.end_time = `${parseSeconds(repaired.start_time) + Number(repaired.duration_seconds)}s`;
  if (!text(repaired.narration_text)) { repaired.narration_text = 'Use safe general wellness narration from the approved script.'; corrections.push(`补充第 ${index + 1} 个镜头旁白占位。`); }
  if (!text(repaired.visual_description)) repaired.visual_description = 'Safe botanical lifestyle visual, no medical claims.';
  if (!text(repaired.shot_type)) repaired.shot_type = 'vertical close-up';
  if (!text(repaired.camera_movement)) repaired.camera_movement = 'slow push-in';
  if (!text(repaired.subject)) repaired.subject = 'herbal tea and botanical props';
  if (!text(repaired.setting)) repaired.setting = 'clean natural wellness setting';
  if (!Array.isArray(repaired.props)) repaired.props = ['herbal tea cup', 'botanical ingredient'];
  if (!text(repaired.on_screen_text)) { repaired.on_screen_text = 'General wellness idea'; corrections.push(`补充第 ${index + 1} 个镜头屏幕文字。`); }
  if (!text(repaired.b_roll_suggestion)) repaired.b_roll_suggestion = 'botanical close-up and calm lifestyle routine';
  if (!text(repaired.image_prompt)) { repaired.image_prompt = safePrompt(repaired); corrections.push(`补充第 ${index + 1} 个镜头 image_prompt。`); }
  if (!text(repaired.video_prompt)) { repaired.video_prompt = safePrompt(repaired).replace('composition', 'short-form video shot'); corrections.push(`补充第 ${index + 1} 个镜头 video_prompt。`); }
  if (!text(repaired.transition)) repaired.transition = 'soft cut';
  if (!text(repaired.continuity_notes)) { repaired.continuity_notes = 'Keep the same vertical 9:16 style, props, color palette, and lighting.'; corrections.push(`补充第 ${index + 1} 个镜头连续性说明。`); }
  if (!text(repaired.safety_notes)) repaired.safety_notes = 'Keep visuals educational and non-clinical; avoid medication scenes, guaranteed outcomes, fake FDA badges, or doctor endorsement.';
  return repaired;
}
function qaPlan(plan) {
  const issues = [];
  const corrections = [];
  const repaired = { ...plan };
  if (repaired.aspect_ratio !== '9:16') { repaired.aspect_ratio = '9:16'; corrections.push('修复画幅为 9:16。'); }
  if (!Array.isArray(repaired.scenes) || repaired.scenes.length === 0) {
    issues.push('缺少 scenes，无法生成可执行镜头表。');
    repaired.scenes = [];
  }
  repaired.scenes = repaired.scenes.map((scene, index) => repairScene(scene, index, corrections));
  const sections = new Set(repaired.scenes.map((scene) => text(scene.script_section)));
  if (!sections.has('Hook')) issues.push('没有覆盖 Hook。');
  if (!sections.has('Body')) issues.push('没有覆盖 Body。');
  if (!sections.has('CTA')) issues.push('没有覆盖 CTA。');
  const first = repaired.scenes[0];
  if (!first || parseSeconds(first.start_time) !== 0 || parseSeconds(first.end_time) > 3.5) issues.push('前 3 秒视觉钩子不明确。');
  const missingPrompt = repaired.scenes.some((scene) => !text(scene.image_prompt) || !text(scene.video_prompt) || !text(scene.on_screen_text) || !text(scene.continuity_notes));
  if (missingPrompt) issues.push('存在镜头缺少 image_prompt、video_prompt、on_screen_text 或连续性说明。');
  const combinedText = JSON.stringify(repaired.scenes);
  const risky = hasRisk(combinedText);
  if (risky.length > 0) issues.push(`出现高风险医疗画面或声明：${Array.from(new Set(risky)).join(', ')}。`);
  const totalDuration = repaired.scenes.reduce((sum, scene) => sum + Number(scene.duration_seconds || 0), 0);
  if (Math.abs(totalDuration - Number(repaired.estimated_duration_seconds || 0)) > 5) {
    repaired.estimated_duration_seconds = totalDuration;
    corrections.push('镜头总时长与预计时长不一致，已按镜头总和调整 estimated_duration_seconds。');
  }
  repaired.scene_count = repaired.scenes.length;
  const qaScore = Math.max(0, 100 - issues.length * 18 - (risky.length > 0 ? 35 : 0));
  const qaPassed = issues.length === 0 && risky.length === 0 && repaired.scenes.length > 0;
  return { ...repaired, qa_passed: qaPassed, qa_score: qaScore, qa_issues: issues, corrections_made: corrections, ready_for_agent5: qaPassed };
}

const qaVisualPlans = (data.draft_visual_plans || []).map((plan) => {
  try {
    return qaPlan(plan);
  } catch (error) {
    return { ...plan, qa_passed: false, qa_score: 0, qa_issues: [`单条视觉方案 QA 失败：${error.message}`], corrections_made: [], ready_for_agent5: false };
  }
});

return [{ json: { ...data, status: 'qa_complete', qa_visual_plans: qaVisualPlans } }];

const data = $input.first()?.json || {};
const generatedAt = new Date().toISOString();
const disclaimer = '本工具仅生成视觉策划、镜头设计和生成式媒体 Prompt，不实际生成图片或视频，也不构成医疗、法律或平台合规意见。最终制作和发布前仍需人工审核。';

function buildReport(status, plans, parseError) {
  const ready = plans.filter((plan) => plan.ready_for_agent5);
  const review = plans.filter((plan) => !plan.ready_for_agent5 && (plan.corrections_made || []).length > 0);
  const failed = plans.filter((plan) => !plan.ready_for_agent5);
  const lines = ['# AI Health OS — Agent 4 Visual Director Report', '', '## 一、本次处理结果', '', `- 状态：${status}`, `- 本次处理脚本数量：${plans.length}`, `- 可进入 Agent 5：${ready.length}`, `- 需要人工复核：${review.length}`, `- 未通过 Visual QA：${failed.length}`];
  if (parseError) lines.push(`- 解析错误：${parseError}`);
  lines.push('', '## 二、可进入 Agent 5 的视觉方案', '');
  lines.push(ready.length ? ready.map((plan) => `- ${plan.video_title}｜QA ${plan.qa_score} 分｜ready_for_agent5 = true`).join('\n') : '- 暂无。');
  lines.push('', '## 三、需要人工复核的视觉方案', '');
  lines.push(review.length ? review.map((plan) => `- ${plan.video_title}｜修改：${(plan.corrections_made || []).join('；') || '无'}`).join('\n') : '- 暂无。');
  lines.push('', '## 四、未通过 Visual QA 的方案', '');
  lines.push(failed.length ? failed.map((plan) => `- ${plan.video_title}｜问题：${(plan.qa_issues || []).join('；') || '未通过 QA'}`).join('\n') : '- 暂无。');
  lines.push('', '## 五、逐镜头视觉执行表', '');
  for (const plan of plans) {
    lines.push(`### ${plan.video_title}`, '', `- 视觉风格：${plan.visual_style}`, `- 画幅：${plan.aspect_ratio}`, `- 预计时长：${plan.estimated_duration_seconds} 秒`, `- QA：${plan.qa_passed ? '通过' : '未通过'}（${plan.qa_score} 分）`, '');
    lines.push('| 镜头编号 | 时间 | 旁白 | 画面 | 屏幕文字 | Image Prompt | Video Prompt | 转场 | 注意事项 |');
    lines.push('| --- | --- | --- | --- | --- | --- | --- | --- | --- |');
    for (const scene of plan.scenes || []) {
      lines.push(`| ${scene.scene_number} | ${scene.start_time}-${scene.end_time} | ${scene.narration_text} | ${scene.visual_description} | ${scene.on_screen_text} | ${scene.image_prompt} | ${scene.video_prompt} | ${scene.transition} | ${scene.safety_notes} |`);
    }
    lines.push('');
  }
  lines.push('## 六、下一步', '', '只有 `ready_for_agent5 = true` 的视觉方案可以交给 Agent 5。当前不要开发 Agent 5，先人工检查镜头方案、画面安全性和品牌风格。', '', '## 重要说明', '', disclaimer);
  return lines.join('\n');
}

let status = 'success';
let visualPlans = Array.isArray(data.qa_visual_plans) ? data.qa_visual_plans : [];
if (data.status === 'error') status = 'error';
if (data.status === 'insufficient_data') status = 'insufficient_data';
if (status !== 'success') visualPlans = [];
const readyCount = visualPlans.filter((plan) => plan.ready_for_agent5).length;
const failedCount = visualPlans.filter((plan) => !plan.ready_for_agent5).length;
const manualReviewCount = visualPlans.filter((plan) => (plan.corrections_made || []).length > 0 || (plan.qa_issues || []).length > 0).length;

return [{ json: { workflow: 'AI Health OS', source_agent: 'agent_3', agent: 'agent_4', version: '0.1', status, generated_at: generatedAt, total_scripts: visualPlans.length, visual_plans: visualPlans, handoff: { next_agent: 'agent_5', ready_count: readyCount, failed_qa_count: failedCount, manual_review_count: manualReviewCount }, disclaimer, parse_error: data.parse_error || '', report_markdown: buildReport(status, visualPlans, data.parse_error || '') } }];
